module::checked_level.body:
{
    if level == 0 || level > MAX_LEVEL {
        return Err(FusionError::Budget {
            what: "SU(2) level (positive)",
            requested: level as u128,
            limit: MAX_LEVEL as u128,
        });
    }
    Ok(())
}

module::quantum_integer.body:
{
    checked_level(level)?;
    if n > 2 * (level + 2) {
        return Err(FusionError::Budget {
            what: "q-integer index",
            requested: n as u128,
            limit: (2 * (level + 2)) as u128,
        });
    }
    let q = root_of_unity::<K>((2 * (level + 2)) as u32, 1)?;
    let numerator = omega_number_theory::scalar::power(&q, n as i64)
        .map_err(FusionError::from)?
        .sub(&omega_number_theory::scalar::power(&q, -(n as i64)).map_err(FusionError::from)?);
    omega_number_theory::scalar::divide(
        &numerator,
        &q.sub(&omega_number_theory::scalar::power(&q, -1).map_err(FusionError::from)?),
    )
    .map_err(FusionError::from)
}

module::triangle_squared.signature:
fn triangle_squared<K: FusionScalar>(
    a: usize,
    b: usize,
    c: usize,
    factorials: &[K],
) -> Result<K, FusionError>

module::triangle_squared.body:
{
    // Private admitted SU(2) triangle: even perimeter <= 2*level.
    let half = (a + b + c) / 2;
    let numerator = factorials[half - a]
        .mul(&factorials[half - b])
        .mul(&factorials[half - c]);
    omega_number_theory::scalar::divide(&numerator, &factorials[half + 1])
        .map_err(FusionError::from)
}

module::racah_term.signature:
fn racah_term<K: FusionScalar>(
    z: usize,
    lower: &[usize; 4],
    upper: &[usize; 3],
    factorials: &[K],
) -> Result<K, FusionError>

module::racah_term.body:
{
    let mut denominator = K::one();
    for &s in lower {
        denominator = denominator.mul(&factorials[z - s]);
    }
    for &s in upper {
        denominator = denominator.mul(&factorials[s - z]);
    }
    omega_number_theory::scalar::divide(&factorials[z + 1], &denominator).map_err(FusionError::from)
}

module::racah_sum.signature:
fn racah_sum<K: FusionScalar>(
    level: usize,
    lower: &[usize; 4],
    upper: &[usize; 3],
    factorials: &[K],
) -> Result<K, FusionError>

module::racah_sum.body:
{
    let start = lower.iter().copied().fold(0, usize::max);
    let end = upper.iter().copied().fold(level, usize::min);
    let mut sum = K::zero();
    for z in start..=end {
        let term = racah_term(z, lower, upper, factorials)?;
        sum = if z % 2 == 0 {
            sum.add(&term)
        } else {
            sum.sub(&term)
        };
    }
    Ok(sum)
}

module::associator.body:
{
    let lower = [
        (a + b + e) / 2,
        (e + c + d) / 2,
        (b + c + f) / 2,
        (a + f + d) / 2,
    ];
    let upper = [
        (a + b + c + d) / 2,
        (a + c + e + f) / 2,
        (b + d + e + f) / 2,
    ];
    let sum = racah_sum(level, &lower, &upper, factorials)?;
    let value = dimensions[e]
        .mul(&triangle_squared(a, b, e, factorials)?)
        .mul(&triangle_squared(e, c, d, factorials)?)
        .mul(&sum);
    Ok(if (a + b + c + d) / 2 % 2 == 0 {
        value
    } else {
        value.neg()
    })
}

module::quantum_dimensions.body:
{
    // Caller admitted 1<=level<=6. One root/inverse and one denominator admission.
    let q = root_of_unity::<K>((2 * (level + 2)) as u32, 1)?;
    let inverse = omega_number_theory::scalar::inverse(&q).map_err(FusionError::from)?;
    let difference = q.sub(&inverse);
    let one =
        omega_number_theory::scalar::divide(&difference, &difference).map_err(FusionError::from)?;
    let step = q.add(&inverse);
    let mut dimensions = Vec::with_capacity(level + 1);
    dimensions.push(one);
    dimensions.push(step.clone());
    for a in 2..=level {
        let next = step.mul(&dimensions[a - 1]).sub(&dimensions[a - 2]);
        dimensions.push(next);
    }
    Ok(dimensions)
}

module::coefficient_data.body:
{
    let dimensions = quantum_dimensions::<K>(level)?;
    let mut factorials = Vec::with_capacity(level + 2);
    factorials.push(K::one());
    for (index, dimension) in dimensions.iter().enumerate() {
        factorials.push(factorials[index].mul(dimension));
    }
    Ok((dimensions, factorials))
}

module::tree_weight.body:
